'use client';
import React,{useEffect,useState,useRef} from 'react';
import {Activity,ArrowUpRight,ArrowDownRight,ArrowRight,ShieldCheck,LayoutDashboard,BriefcaseBusiness,ChartNoAxesCombined,FlaskConical,Network,ScanEye,Lightbulb,ClipboardCheck,FileChartColumn,Settings2,Search,Bell,ChevronDown,Play,Plus,Download,Upload,X,Check,Trash2,RefreshCw,LogIn,LogOut,Menu,Command,ChevronRight,ExternalLink,Send,Info,CheckCircle2,Clock,TriangleAlert,Pencil} from 'lucide-react';
